  "itemListElement": [
    { "@type": "Service", "position": 1, "name": "Laudo para Auxílio-Doença", "url": "https://nexus-relatorios.netlify.app/#servicos", "provider": { "@type": "MedicalBusiness", "name": "Nexus Relatórios" }, "areaServed": "BR" },
    { "@type": "Service", "position": 2, "name": "Laudo para Auxílio-Acidente", "url": "https://nexus-relatorios.netlify.app/#servicos", "provider": { "@type": "MedicalBusiness", "name": "Nexus Relatórios" }, "areaServed": "BR" },
    { "@type": "Service", "position": 3, "name": "Laudo para BPC/LOAS", "url": "https://nexus-relatorios.netlify.app/#servicos", "provider": { "@type": "MedicalBusiness", "name": "Nexus Relatórios" }, "areaServed": "BR" },
    { "@type": "Service", "position": 4, "name": "Relatórios para Seguradoras", "url": "https://nexus-relatorios.netlify.app/#servicos", "provider": { "@type": "MedicalBusiness", "name": "Nexus Relatórios" }, "areaServed": "BR" }
  ]
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Qual o prazo para receber meu laudo ou relatório médico?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "O prazo padrão de entrega é de até 24 horas a partir da confirmação e envio de toda a documentação necessária, garantindo agilidade sem comprometer a qualidade técnica do laudo ou relatório."
      }
    },
    {
      "@type": "Question",
      "name": "Como funciona o atendimento por videochamada?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Após o agendamento, você recebe um link de acesso à videochamada. A consulta é realizada por um médico especializado, que realizará a avaliação clínica necessária para elaboração do laudo ou relatório. Todo o processo é remoto, seguro e atende clientes em qualquer parte do Brasil."
      }
    },
    {
      "@type": "Question",
      "name": "Quais documentos preciso apresentar?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A lista varia conforme o tipo de serviço, mas geralmente inclui: documentos de identificação pessoal, histórico médico (exames, prescrições e laudos anteriores), CNIS e documentos relativos à doença ou condição incapacitante. Nossa equipe orientará você sobre tudo que é necessário em cada caso."
      }
    },
    {
      "@type": "Question",
      "name": "Os laudos da Nexus Relatórios são aceitos pelo INSS?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Sim. Todos os laudos e relatórios são elaborados por médicos com registro ativo no CRM, seguindo os padrões técnicos exigidos pelo INSS e pelas seguradoras. Os documentos possuem assinatura digital com certificado ICP-Brasil e são amplamente utilizados por escritórios de advocacia parceiros em processos administrativos e judiciais."
      }
    },
    {
      "@type": "Question",
      "name": "Como funciona o pagamento?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Aceitamos pagamento via PIX, transferência bancária, cartão de crédito (parcelamento disponível) ou boleto bancário. Os valores variam conforme o tipo e complexidade do serviço. Após a análise do caso, apresentamos um orçamento detalhado sem compromisso."
      }
    }
  ]
}

body.script:
'use strict';

/* --- Navbar scroll --- */
const navbar   = document.getElementById('navbar');
const sections = document.querySelectorAll('section[id]');
const navLinks = document.querySelectorAll('.nav-link[href^="#"]');

function onScroll() {
  const y = window.scrollY;
  navbar.classList.toggle('scrolled', y > 60);

  // Active link
  let current = '';
  sections.forEach(s => { if (y >= s.offsetTop - 130) current = s.id; });
  navLinks.forEach(l => {
    l.classList.toggle('active', l.getAttribute('href') === '#' + current);
  });

  // Floating CTA
  document.getElementById('floatingCta').classList.toggle('visible', y > 500);
}
window.addEventListener('scroll', onScroll, { passive: true });

/* --- Mobile menu --- */
function openMobileMenu() {
  const m = document.getElementById('mobileMenu');
  const btn = document.getElementById('menuToggle');
  m.style.display = 'flex';
  requestAnimationFrame(() => m.classList.add('open'));
  btn.classList.add('open');
  btn.setAttribute('aria-expanded', 'true');
  btn.setAttribute('aria-label', 'Fechar menu');
  document.body.style.overflow = 'hidden';
}
function closeMobileMenu() {
  const m = document.getElementById('mobileMenu');
  const btn = document.getElementById('menuToggle');
  m.classList.remove('open');
  setTimeout(() => { m.style.display = 'none'; }, 350);
  btn.classList.remove('open');
  btn.setAttribute('aria-expanded', 'false');
  btn.setAttribute('aria-label', 'Abrir menu');
  document.body.style.overflow = '';
}
function toggleMobileMenu() {
  const btn = document.getElementById('menuToggle');
  if (btn.classList.contains('open')) { closeMobileMenu(); } else { openMobileMenu(); }
}

/* --- Intersection observer (animations) --- */
const io = new IntersectionObserver((entries) => {
  entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); });
}, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

document.querySelectorAll(
  '[data-animate], .section-label, .section-title, .section-subtitle, ' +
  '.service-card, .diferencial, .depoimento-card, .faq-item, .pillar, ' +
  '.sobre-visual, .sobre-content, .contato-info, .form-card'
).forEach(el => io.observe(el));

/* --- FAQ --- */
function toggleFaq(btn) {
  const item   = btn.parentElement;
  const answer = item.querySelector('.faq-answer');
  const isOpen = item.classList.contains('open');
  const expanded = !isOpen;

  document.querySelectorAll('.faq-item.open').forEach(o => {
    o.classList.remove('open');
    o.querySelector('.faq-answer').style.maxHeight = '0';
    o.querySelector('.faq-question').setAttribute('aria-expanded', 'false');
  });

  if (!isOpen) {
    item.classList.add('open');
    answer.style.maxHeight = answer.scrollHeight + 'px';
    btn.setAttribute('aria-expanded', 'true');
  }
}

/* Keyboard support for FAQ */
document.querySelectorAll('.faq-question').forEach(btn => {
  btn.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleFaq(btn); }
  });
});

/* --- Phone mask --- */
document.getElementById('telefone').addEventListener('input', function () {
  let v = this.value.replace(/\D/g, '').slice(0, 11);
  if (v.length >= 2) v = '(' + v.slice(0,2) + ') ' + v.slice(2);
  if (v.length >= 10) v = v.slice(0,10) + '-' + v.slice(10);
  this.value = v;
});

/* --- Form validation --- */
const validateEmail = v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v);
const validatePhone = v => v.replace(/\D/g,'').length >= 10;

function liveValidate(el, fn) {
  el.addEventListener('blur', () => {
    const ok = fn(el.value);
    el.classList.toggle('valid', ok);
    el.classList.toggle('error', !ok);
  });
  el.addEventListener('input', () => {
    if (el.classList.contains('error') && fn(el.value)) {
      el.classList.remove('error');
      el.classList.add('valid');
    }
  });
}
liveValidate(document.getElementById('nome'),     v => v.trim().length > 2);
liveValidate(document.getElementById('email'),    validateEmail);
liveValidate(document.getElementById('telefone'), validatePhone);

document.getElementById('contactForm').addEventListener('submit', async function (e) {
  e.preventDefault();

  /* ---- Validação ---- */
  const nome    = document.getElementById('nome');
  const email   = document.getElementById('email');
  const tel     = document.getElementById('telefone');
  const servico = document.getElementById('servico');
  let ok = true;

  [[nome, v => v.trim().length > 2], [email, validateEmail], [tel, validatePhone]].forEach(([el, fn]) => {
    const valid = fn(el.value);
    el.classList.toggle('valid', valid);
    el.classList.toggle('error', !valid);
    if (!valid) ok = false;
  });
  if (!ok) return;

  /* ---- UI: estado enviando ---- */
  const btn = document.getElementById('submitBtn');
  const originalText = btn.textContent;
  btn.textContent = 'Enviando...';
  btn.classList.add('sending');
  btn.disabled = true;

  /* ---- Montar mensagem WhatsApp ---- */
  const nomeVal    = nome.value.trim();
  const telVal     = tel.value.trim();
  const emailVal   = email.value.trim();
  const servicoVal = servico.value || 'Não informado';
  const msgVal     = (document.getElementById('mensagem').value || '').trim();

  const wppMsg = encodeURIComponent(
    '📋 *Nova mensagem via site — Nexus Relatórios*\n\n' +
    '👤 *Nome:* ' + nomeVal + '\n' +
    '📱 *WhatsApp:* ' + telVal + '\n' +
    '📧 *E-mail:* ' + emailVal + '\n' +
    '🩺 *Serviço:* ' + servicoVal + '\n' +
    (msgVal ? '💬 *Mensagem:* ' + msgVal : '')
  );
  const wppURL = 'https://wa.me/554396810795?text=' + wppMsg;

  /* ---- Envio para Netlify Forms ---- */
  try {
    const formData = new FormData(this);
    const res = await fetch('/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams(formData).toString()
    });

    if (res.ok) {
      /* Sucesso: mostra confirmação e abre WhatsApp */
      document.getElementById('contactForm').style.display     = 'none';
      document.getElementById('formErrorBanner').style.display = 'none';
      document.getElementById('formSuccess').style.display     = 'block';
      /* Pequeno delay para o usuário ver a confirmação antes do WhatsApp abrir */
      setTimeout(() => { window.open(wppURL, '_blank', 'noopener'); }, 800);
    } else {
      throw new Error('Resposta inesperada: ' + res.status);
    }
  } catch (err) {
    /* Falha real no envio: informa o usuário honestamente, mas mantém o
       WhatsApp como canal alternativo, já que ele independe do Netlify. */
    console.warn('Netlify Forms error:', err);
    document.getElementById('contactForm').style.display     = 'none';
    document.getElementById('formSuccess').style.display     = 'none';
    document.getElementById('formErrorBanner').style.display = 'block';

    setTimeout(() => { window.open(wppURL, '_blank', 'noopener'); }, 800);
  } finally {
    btn.disabled = false;
    btn.classList.remove('sending');
    btn.textContent = originalText;
  }
});

/* ---- Botão "Tentar novamente" no banner de erro ---- */
document.getElementById('formRetryBtn').addEventListener('click', function () {
  document.getElementById('formErrorBanner').style.display = 'none';
  document.getElementById('contactForm').style.display      = '';
});

/* --- Smooth scroll for all anchor links --- */
document.querySelectorAll('a[href^="#"]').forEach(a => {
  a.addEventListener('click', e => {
    const t = document.querySelector(a.getAttribute('href'));
    if (t) { e.preventDefault(); t.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
  });
});

/* Keyboard support for nav logo */
document.querySelector('.nav-logo').addEventListener('keydown', e => {
  if (e.key === 'Enter') window.scrollTo({ top: 0, behavior: 'smooth' });
});
